D('dom-append-child','Adaugă un element cu appendChild','createElement construiește un nod. appendChild îl introduce la finalul listei de copii; simpla creare nu îl afișează.','const item=document.createElement("li"); item.textContent="Tea"; document.querySelector("ul").appendChild(item);','<ul><li>Cake</li></ul>',[count('ul > li',2),exact('ul > li:last-child','Tea')],'Păstrează Cake și adaugă la finalul listei un li cu text Tea, folosind createElement și appendChild.')
D('dom-insert-before','Inserează înaintea unui nod','insertBefore(newNode,referenceNode) inserează în părintele pe care îl apelezi. Nodul de referință trebuie să fie copil al acelui părinte.','const list=document.querySelector("ul"); const item=document.createElement("li"); item.textContent="Tea"; list.insertBefore(item,list.firstElementChild);','<ul><li>Cake</li></ul>',[count('ul > li',2),exact('ul > li:first-child','Tea'),exact('ul > li:last-child','Cake')],'Adaugă un li Tea înainte de Cake cu insertBefore, păstrând Cake.')
D('dom-get-elements-name','Grupează controale după name','getElementsByName caută atributul name, nu id sau clasa. Este util pentru grupuri radio. Iterează colecția pentru a găsi controlul bifat.','const selected=Array.from(document.getElementsByName("kind")).find(control=>control.checked); document.querySelector("output").textContent=selected.value;','<label><input name="kind" type="radio" value="cake">Cake</label><label><input name="kind" type="radio" value="tea" checked>Tea</label><output></output>',[exact('output','tea')],'Citește grupul kind cu getElementsByName și afișează în output valoarea controlului bifat.')
D('dom-template-clone','Reutilizează un template HTML','Conținutul unui template este inert. Clonează content și atașează fragmentul în pagină; cloneNode(true) include descendenții.','const fragment=document.querySelector("template").content.cloneNode(true); fragment.querySelector("h2").textContent="Tea"; document.querySelector("main").appendChild(fragment);','<template><article><h2></h2></article></template><main></main>',[exact('main > article > h2','Tea')],'Clonează conținutul template-ului, pune Tea în h2 și adaugă fragmentul în main.')
H('html-table-headers','Asociază celulele cu antetele','scope descrie rolul antetului. headers poate lega explicit o celulă de unul sau mai multe antete identificate prin id.','<table><tr><th id="price" scope="col">Price</th></tr><tr><td headers="price">12</td></tr></table>',[attr('th','id','price'),attr('th','scope','col'),attr('td','headers','price'),exact('td','12')],'Creează un tabel cu antet Price, id price și scope col. Celula 12 trebuie să indice antetul prin headers.')
H('html-srcset-density','Imagini pentru densități diferite','Descriptorii 1x și 2x indică densitatea pixelilor. Nu îi amesteca în aceeași listă cu descriptorii de lățime w.','<img src="tea.png" srcset="tea.png 1x, tea-retina.png 2x" alt="Tea">',[attr('img','src','tea.png'),attr('img','srcset','tea.png 1x, tea-retina.png 2x'),attr('img','alt','Tea')],'Scrie un img cu src tea.png, alt Tea și srcset tea.png 1x, tea-retina.png 2x. Fișierele sunt numele alese pentru noul tău proiect; verificăm declararea resurselor.')
H('html-meter-ranges','Limite și valoare optimă pentru meter','meter reprezintă o măsurătoare într-un interval cunoscut. low, high și optimum descriu interpretarea valorii; nu înlocuiesc min, max sau value.','<meter min="0" max="100" low="20" high="80" optimum="50" value="60">60/100</meter>',[attr('meter',k,v) for k,v in [('min','0'),('max','100'),('low','20'),('high','80'),('optimum','50'),('value','60')]],'Reprezintă măsurătoarea 60 din 100 cu meter, min 0, low 20, high 80 și optimum 50. Include text fallback.')
H('html-progress','Progresul unei operații','progress descrie avansul unei operații, în timp ce meter descrie o măsurătoare. value și max permit exprimarea progresului determinat.','<label>Upload <progress value="3" max="10">3/10</progress></label>',[attr('progress','value','3'),attr('progress','max','10'),exact('progress','3/10')],'Creează un progress pentru 3 pași din 10, cu text fallback 3/10 și etichetă Upload.')
H('html-canvas-fallback','Pregătește o suprafață canvas','canvas are atribute width și height pentru dimensiunea suprafeței de desenare. Textul interior este fallback; desenarea propriu-zisă se face prin JavaScript.','<canvas width="300" height="150">Sales chart</canvas>',[attr('canvas','width','300'),attr('canvas','height','150'),exact('canvas','Sales chart')],'Pregătește un canvas cu suprafața de 300 pe 150 și fallback Sales chart.')

for old,code,tests,idea in [
 ('big','<span class="large">Cake</span>',[exact('span.large','Cake')],'big era folosit pentru dimensiune. Alege un element potrivit conținutului și controlează mărimea prin CSS.'),
 ('dir','<ul><li>Images</li></ul>',[exact('ul > li','Images')],'dir este învechit; o listă obișnuită se exprimă prin ul și li.'),
 ('basefont','<p class="page-text">Cake</p>',[exact('p.page-text','Cake')],'basefont este învechit. Fontul general se stabilește în CSS, de exemplu pe body.'),
 ('applet','<canvas width="300" height="150">Interactive chart</canvas>',[count('canvas')],'applet încorpora aplicații Java și este învechit. Alege o implementare web potrivită funcției, de exemplu canvas plus JavaScript pentru un grafic.'),
 ('noframes','<main><h1>Products</h1></main>',[exact('main > h1','Products')],'frame și noframes aparțineau structurii frameset. Construiește o pagină obișnuită cu secțiuni și CSS, fără vechea împărțire în frame-uri.'),
]:
 H('html-modern-'+old,'Înlocuiește '+old,idea,code,tests,'Rescrie conținutul folosind structura modernă din exemplu: '+code)

T('validation-html','Validează HTML-ul rezultat','Un validator HTML primește documentul trimis browserului. Un template EJS trebuie randat înainte; afișarea aparent corectă nu garantează validitatea.','Template: <h1><%= name %></h1>\nRendered HTML: <h1>Tea</h1>',q('Ce trimiți unui validator HTML?','HTML-ul randat','Template-ul EJS neexecutat','Schema PostgreSQL'),'Alege fragmentul potrivit validatorului: scrie exact HTML-ul randat din situația dată.','<h1>Tea</h1>')
T('validation-recheck','Corectează și revalidează','O singură închidere greșită poate genera mai multe mesaje. Corectează cauza, apoi revalidează documentul pentru a vedea erorile rămase.','Invalid: <b><i>Tea</b></i>\nValid: <b><i>Tea</i></b>',q('Ce faci după corectarea unei erori de imbricare?','Revalidezi documentul','Ignori toate erorile viitoare','Ștergi DOCTYPE'),'Rescrie fragmentul invalid cu etichetele închise în ordine inversă deschiderii.','<b><i>Tea</i></b>')
T('compatibility-feature-detect','Detectează o funcționalitate','Un polyfill implementează o funcționalitate lipsă. Detectează întâi disponibilitatea; numele browserului nu este o verificare a fiecărei funcții.','const available = typeof Array.prototype.flat === "function";',q('Ce verifică expresia?','Disponibilitatea funcției flat','Dacă există acces la internet','Numele serverului'),'Ce metodă Array este verificată în expresia de mai sus? Scrie numele metodei.','flat')
T('mathjax-role','Rolul unui renderer de formule','MathML descrie formula. MathJax poate interpreta notații matematice și produce afișaj. Configurația și încărcarea bibliotecii sunt diferite de scrierea formulei.','MathML or TeX → MathJax → rendered formula',q('Ce reprezintă MathML în acest traseu?','O notație de intrare pentru formulă','O bază de date','Un protocol de email'),'Scrie numele componentei care transformă notația în afișaj în traseul dat.','MathJax')
T('icons-classes','Compune clasele unui icon','O bibliotecă de iconuri combină o clasă pentru stil cu numele iconului și eventual dimensiune, rotație sau animație. Un icon decorativ poate fi ascuns tehnologiilor asistive dacă textul alăturat îi explică sensul.','<span class="fas fa-star fa-fw fa-spin" aria-hidden="true"></span> Favorite',q('Ce clasă din exemplu indică rotația continuă?','fa-spin','fa-star','fa-fw'),'Păstrezi iconul, dar vrei să elimini rotația continuă. Scrie clasa pe care o elimini.','fa-spin')

for id,title,code,tests,prompt in [
 ('css-media-and','Combină condițiile media','@media screen and (min-width:500px) and (max-width:900px){.card{color:navy}}',[dict(prop('.card','color','rgb(0, 0, 128)'),viewport=700),dict(prop('.card','color','rgb(0, 0, 0)'),viewport=1000)],'Colorează .card navy doar pe ecran între 500 și 900px inclusiv, folosind and.'),
 ('css-media-or','Alternative în media query','@media (max-width:400px), (min-width:1000px){.card{color:navy}}',[dict(prop('.card','color','rgb(0, 0, 128)'),viewport=350),dict(prop('.card','color','rgb(0, 0, 0)'),viewport=700),dict(prop('.card','color','rgb(0, 0, 128)'),viewport=1100)],'Folosește o listă media cu virgulă: .card devine navy sub 400px inclusiv sau de la 1000px inclusiv.'),
 ('css-media-not','Neagă o interogare media','@media not all and (min-width:500px){.card{color:navy}}',[dict(prop('.card','color','rgb(0, 0, 128)'),viewport=400),dict(prop('.card','color','rgb(0, 0, 0)'),viewport=800)],'Folosește not all and (min-width:500px) pentru a colora .card navy când lățimea este sub 500px.'),
 ('css-media-nested','Interogări media imbricate','@media screen and (min-width:500px){@media (max-width:900px){.card{color:navy}}}',[dict(prop('.card','color','rgb(0, 0, 128)'),viewport=700),dict(prop('.card','color','rgb(0, 0, 0)'),viewport=1000)],'Imbrică o regulă max-width:900px într-o regulă screen and min-width:500px. Între limite, .card are color navy.'),
]:
 idea='Condițiile media aleg când sunt aplicate regulile. and cere ambele condiții, virgula oferă alternative, not neagă interogarea, iar imbricarea cere satisfacerea condițiilor exterioare și interioare.'
 lesson(c,id,title,idea,code,idea,q('Când se aplică regula imbricată?','Când toate condițiile de pe traseu sunt adevărate','Indiferent de regula exterioară','Numai pe server'),css(prompt,code,'<p class="card">Tea</p>',tests))

H('html-heading-group','Grupează titlul și subtitlul','hgroup poate grupa un heading cu textul său secundar. Titlul rămâne un heading real, iar subtitlul poate fi un paragraf.','<hgroup><h1>Sweet Corner</h1><p>Fresh every day</p></hgroup>',[exact('hgroup > h1','Sweet Corner'),exact('hgroup > p','Fresh every day')],'Grupează în hgroup titlul h1 Sweet Corner și subtitlul p Fresh every day.')
lesson(c,'js-locale-sensitivity','Compară textul fără accente sau registru','localeCompare poate primi limba și opțiunea sensitivity. Cu en și base, diferențele de registru și accentele nu disting cuvintele din aceste exemple.','function solve(input){return input.left.localeCompare(input.right,"en",{sensitivity:"base"})===0;}','Compară egalitatea prin rezultatul zero; pentru sortare folosește semnul rezultatului, fără să presupui că este exact -1 sau 1.',q('Ce indică rezultatul zero al localeCompare?','Echivalență conform opțiunilor','Primul text este întotdeauna mai scurt','O eroare de parsare'),js('Primești {left,right}. Returnează dacă textele sunt echivalente cu localeCompare pentru en și sensitivity base.','function solve(input){return input.left.localeCompare(input.right,"en",{sensitivity:"base"})===0;}',[({'left':'café','right':'CAFE'},True),({'left':'tea','right':'cake'},False)]))
lesson(c,'css-import-stylesheet','Importă o foaie de stil','@import poate include altă foaie de stil CSS. Este o regulă CSS, distinctă de @use și @forward din Sass; ordinea foilor și a regulilor influențează cascada.','@import url("theme.css");\n.card{color:navy;}','În acest exercițiu verificăm declarația importului. Resursa externă nu este descărcată în previzualizarea izolată.',q('În ce limbaj există această regulă @import?','CSS','SQL','EJS'),css('Declară @import url("theme.css") înaintea regulii .card cu color navy. Exercițiul verifică declarația, fără descărcarea foii externe.','@import url("theme.css");\n.card{color:navy;}','<p class="card">Tea</p>',[dict(kind='cssIncludes',value='@import url("theme.css");',label='Importul foii theme.css'),prop('.card','color','rgb(0, 0, 128)')]))
lesson(c,'css-grid-dense','Completează spațiile libere ale grilei','grid-auto-flow:row dense permite completarea golurilor cu elemente care încap. Ordinea vizuală se poate deosebi de ordinea DOM, importantă pentru citire și navigare.','.grid{display:grid;grid-template-columns:repeat(3,1fr);grid-auto-flow:row dense;}','dense schimbă modul de plasare automată, fără să modifice ordinea nodurilor în document.',q('Modifică dense ordinea DOM?','Nu','Da, mută nodurile','Numai la printare'),css('Creează pe .grid trei coloane egale și setează grid-auto-flow row dense.','.grid{display:grid;grid-template-columns:repeat(3,1fr);grid-auto-flow:row dense;}','<div class="grid"><p>A</p><p>B</p><p>C</p></div>',[cols('.grid',3),dict(kind='cssIncludes',value='grid-auto-flow:row dense',label='Plasare row dense')]))

c=chapter('node-integration','Node · de la fișiere la HTTP și date','Directoare, HTTP nativ și legătura dintre baza de date și pagină.','Node și Express - introducere.pptx; serverul proiectului și SQL','server')
def N(id,title,idea,code,cases,prompt,files=None):
 lesson(c,id,title,idea,code,idea,q('Unde rulează acest cod?','În Node','În motorul CSS','Într-o regulă DNS'),js(prompt,code,cases,mode='node',files=files or {}))
N('node-mkdir-sync','Creează directoare sincron','mkdirSync cu recursive:true creează și părinții lipsă. Operația sincronă se termină înainte de următoarea instrucțiune. Lucrezi doar în sistemul virtual al exercițiului.','const fs=require("fs"); function solve(input){fs.mkdirSync(input,{recursive:true});return fs.existsSync(input)&&fs.lstatSync(input).isDirectory();}',[('images/products',True),('cache/previews',True)],'Primești o cale relativă. Creează directorul și părinții lipsă cu mkdirSync recursive, apoi returnează dacă există și este director.')
N('node-mkdir-callback','Așteaptă crearea directorului','mkdir este asincron: continuarea care depinde de rezultat intră în callback sau după await. Nu presupune că directorul există imediat după lansarea operației.','const fs=require("fs"); function solve(input){return new Promise((resolve,reject)=>fs.mkdir(input,{recursive:true},error=>{if(error)reject(error);else resolve(fs.lstatSync(input).isDirectory());}));}',[('cache/thumbs',True)],'Returnează un Promise: creează input cu fs.mkdir recursive și confirmă în callback că este director. Respinge Promise-ul dacă apare o eroare.')
N('node-dirname-filename','Locul fișierului executat','__dirname este directorul modulului CommonJS, iar __filename este calea fișierului. Aceste valori nu reprezintă automat directorul curent al terminalului.','function solve(input){return {directory:__dirname,file:__filename};}',[(None,{'directory':'/project','file':'/project/app.js'})],'Returnează {directory,file} folosind __dirname și __filename. Modulul de antrenament este /project/app.js.')
N('node-legacy-url','Descompune adresa cu url.parse','Materialele vechi pot folosi url.parse și querystring.parse. URL și URLSearchParams oferă alternativa modernă. Înțelege ce parte este cale și ce parte este query înainte de migrare.','const url=require("url"),querystring=require("querystring"); function solve(input){const parsed=url.parse(input);const query=querystring.parse(parsed.query);return {path:parsed.pathname,name:query.name};}',[('/products?name=Tea',{'path':'/products','name':'Tea'}),('/products?name=Ice%20cream',{'path':'/products','name':'Ice cream'})],'Folosește url.parse și querystring.parse pentru a returna {path,name}. Decodifică valoarea name din query.')

code='''const http=require("http");
const server=http.createServer((req,res)=>{
 if(req.url==="/health") {res.writeHead(200,{"Content-Type":"text/plain"});res.write("Ready");res.end();}
 else {res.writeHead(404,{"Content-Type":"text/plain"});res.end("Not found");}
});
module.exports=server;'''
lesson(c,'node-native-http','Construiește un server HTTP nativ','http.createServer înregistrează handler-ul de cereri. writeHead stabilește statusul și antetele, write adaugă date, iar end încheie răspunsul. În laborator exporți serverul; nu deschizi un port cu listen.',code,'Un handler primește req și res. Fiecare ramură trebuie să încheie răspunsul o singură dată.',q('Care metodă încheie răspunsul HTTP?','res.end','res.writeHead','http.createServer'),express('Folosește http.createServer. /health răspunde 200 Ready; orice altă cale, 404 Not found. Setează Content-Type text/plain și exportă serverul fără listen.',code,[dict(path='/health',bodyExpected='Ready'),dict(path='/missing',status=404,bodyExpected='Not found')],starter='const http=require("http");\n\n// Create and export the server.\n'))

T('node-npm-install','Instalează dependențele proiectului','npm install fără nume de pachet citește dependențele proiectului. node_modules este rezultatul instalării; package.json descrie dependențele directe. Acesta este un exercițiu despre construirea unui proiect propriu.','New project: package.json contains dependencies\nNo node_modules directory yet',q('Ce comandă instalează dependențele declarate?','npm install','npm uninstall','npm ls'),'Ai primit propriul proiect cu package.json, fără pachetele instalate. Scrie comanda care instalează dependențele declarate.','npm install')
T('node-process-exit','Codul de ieșire al procesului','process.exit termină procesul Node cu un cod de stare. Zero indică în mod convențional succes; o valoare nenulă indică eșec. Nu confunda încheierea unei cereri HTTP cu încheierea întregului proces.','process.exit(1);',q('Ce se încheie prin process.exit?','Procesul Node','Doar un răspuns HTTP','Doar o animație CSS'),'Ce cod de ieșire folosește exemplul?','1')
for operation,command,idea in [('update','npm update express','Actualizarea dependenței trebuie urmată de verificarea compatibilității aplicației.'),('uninstall','npm uninstall express','Dezinstalarea unei dependențe o elimină din proiect și actualizează declarația pachetelor.'),('list','npm ls','Arborele dependențelor arată pachetele instalate și relațiile dintre ele.')]:
 T('node-npm-'+operation,'npm · '+operation,idea,command,q('Ce unealtă gestionează pachetele?','npm','HTML','PostgreSQL'),'Scrie comanda din exemplu pentru operația '+operation+'.',command)
T('node-send-file','Trimite un fișier cu sendFile','res.sendFile trimite conținutul unui fișier. O cale relativă trebuie rezolvată prin opțiunea root; o cale absolută poate fi construită cu path.join. Nu confunda trimiterea fișierului cu randarea EJS.','res.sendFile("guide.html", {root: path.join(__dirname,"public")});',q('Ce trimite sendFile?','Conținutul fișierului','Numele fișierului ca text','Un template EJS randat'),'Din exemplul dat, scrie numele opțiunii care stabilește directorul de bază pentru calea relativă.','root')
T('node-pg-connect','Deschide conexiunea PostgreSQL','Clientul pg se conectează înainte de interogare. Operațiile asincrone trebuie așteptate; parametrii $1, $2 separă valorile de textul interogării. Datele bazei de antrenament nu sunt credențiale de producție.','await client.connect();\nconst result=await client.query("SELECT name FROM products WHERE id=$1",[id]);\nawait client.end();',q('Unde se transmite valoarea id?','În vectorul parametrilor','Prin concatenare în SQL','În selectorul CSS'),'Scrie marcajul parametrului SQL folosit pentru id în exemplu.','$1')

lesson(c,'date-local-month','Luna în timpul local','getMonth întoarce luna locală în intervalul 0–11. Pentru date UTC folosește getUTCMonth; nu amesteca aceste convenții.', 'function solve(input){return new Date(input.year,input.month-1,1).getMonth()+1;}', 'Constructorul numeric folosește luna de la zero, iar rezultatul este convertit la intervalul 1–12.',q('Ce întoarce getMonth pentru ianuarie?','0','1','12'),js('Primești {year,month}, cu month între 1 și 12. Construiește data locală pentru ziua 1 și returnează luna în intervalul 1–12 folosind getMonth.','function solve(input){return new Date(input.year,input.month-1,1).getMonth()+1;}',[({'year':2025,'month':1},1),({'year':2025,'month':12},12)]))

