H('html-thematic-break','Separă teme cu hr','hr reprezintă o schimbare tematică între blocuri de conținut. Nu este doar o linie decorativă; pentru decor folosește CSS.','<p>Our story</p><hr><p>Our products</p>',[count('hr'),count('p',2)],'Scrie paragrafele Our story și Our products, separate prin hr.')
H('html-description-list','Termeni și descrieri','dl grupează perechi de termeni dt și descrieri dd. Nu înlocuiește automat orice listă ul sau tabel.','<dl><dt>Tea</dt><dd>Hot drink</dd></dl>',[exact('dl > dt','Tea'),exact('dl > dd','Hot drink')],'Construiește o listă de descrieri: termenul Tea și descrierea Hot drink.')
H('html-data-value','Valoare citibilă de mașină','data asociază textul vizibil cu o valoare din atributul value. Nu este același lucru cu atributul global data-*.','<data value="P7">Chocolate cake</data>',[attr('data','value','P7'),exact('data','Chocolate cake')],'Afișează Chocolate cake într-un element data cu identificatorul P7 în value.')
H('html-menu-list','Meniu exprimat ca listă','menu poate reprezenta o listă de comenzi. Pentru navigarea între pagini, nav cu o listă de legături exprimă rolul explicit.','<menu><li><button type="button">Save</button></li></menu>',[exact('menu > li > button','Save'),attr('button','type','button')],'Creează un menu cu un li și un buton Save de tip button.')
H('html-internal-style','Stil în document','style conține CSS. Spre deosebire de atributul style de pe un element, poate include reguli pentru mai mulți selectori.','<style>.notice{color:navy}</style><p class="notice">Tea</p>',[count('style'),prop('.notice','color','rgb(0, 0, 128)')],'Adaugă un style care face .notice navy și un paragraf .notice cu Tea.')
H('html-script-defer','Încarcă un script după parsare','Un script extern cu defer este descărcat fără blocarea parsării și executat după parsarea documentului. În exercițiul HTML verificăm declarația, fără a executa fișierul extern.','<script src="app.js" defer></script>',[dict(kind='sourceAttr',selector='script',name='src',value='app.js',label='Scriptul declară app.js'),dict(kind='sourceAttr',selector='script',name='defer',value='',label='Scriptul are defer')],'Declară un script extern app.js cu defer. Nu trebuie să ai fișierul pe calculator.')
H('html-object-resource','Resursă încorporată cu fallback','object declară data și type pentru o resursă încorporată, plus conținut fallback. Previziunile izolate nu încarcă resursa externă; verificăm declararea ei.','<object data="guide.pdf" type="application/pdf">Download the guide</object>',[dict(kind='sourceAttr',selector='object',name='data',value='guide.pdf',label='Resursa este guide.pdf'),dict(kind='sourceAttr',selector='object',name='type',value='application/pdf',label='Tipul este application/pdf'),dict(kind='sourceText',selector='object',value='Download the guide',label='Există textul fallback')],'Declară un object pentru guide.pdf, type application/pdf, cu fallback Download the guide.')
D('dom-select-by-id','Selectează un id','getElementById primește valoarea id fără simbolul #. Returnează un singur element sau null.','document.getElementById("status").textContent="Ready";','<p id="status">Waiting</p>',[exact('#status','Ready')],'Folosește getElementById pentru a schimba textul elementului status în Ready.')
D('dom-select-by-class','Colecție după clasă','getElementsByClassName primește numele clasei fără punct și returnează o colecție live. Array.from produce o copie pe care o poți itera stabil.','for(const item of Array.from(document.getElementsByClassName("product")))item.classList.add("ready");','<p class="product">Cake</p><p class="product">Tea</p>',[count('.product.ready',2)],'Adaugă clasa ready tuturor elementelor product, selectând cu getElementsByClassName.')
D('dom-class-contains','Verifică o clasă existentă','classList.contains testează un token de clasă complet. Nu verifică un subșir din numele clasei.','document.querySelector("output").textContent=String(document.querySelector("main").classList.contains("dark"));','<main class="dark compact"></main><output></output>',[exact('output','true')],'Afișează în output dacă main are clasa dark, folosind classList.contains și String.')
T('storage-remove-one','Șterge o singură preferință','removeItem șterge cheia indicată; clear șterge toate intrările acelei zone de stocare. Eliminarea unei teme nu trebuie să elimine automat și coșul.','localStorage.setItem("theme","dark");\nlocalStorage.setItem("cart","[]");\nlocalStorage.removeItem("theme");',q('Ce cheie rămâne după codul dat?','cart','theme','Niciuna'),'Scrie cheia care rămâne în localStorage după cele trei operații.','cart')
T('mathjax-historical-config','Configurația MathJax din cod vechi','MathJax.Hub.Config apare în configurații MathJax 2. Configurația aparține versiunii bibliotecii; nu o confunda cu un element MathML sau cu API-ul altei versiuni.','MathJax.Hub.Config({MathML:{extensions:["mml3.js"]}});',q('Ce configurează apelul?','Biblioteca MathJax 2','Un tabel PostgreSQL','Motorul Express'),'Scrie numele extensiei declarate în configurația dată.','mml3.js')
T('vtt-cue-layout','Alinierea și dimensiunea subtitrării','Setările unui cue WebVTT vin pe linia intervalului, după momentul final. align controlează alinierea, iar size lățimea zonei; sunt distincte de CSS ::cue.','WEBVTT\n\n00:00:01.000 --> 00:00:03.000 align:start size:50%\nFresh tea',q('Unde sunt setările cue-ului?','După timpul final','Înainte de WEBVTT','Într-o instrucțiune SELECT'),'Scrie setările care aliniază la început și folosesc 50% din lățime, exact ca în exemplu.','align:start size:50%')
lesson(c,'css-animation-direction-long','Direcția animației','animation-direction controlează sensul fiecărui ciclu. alternate schimbă sensul la ciclurile succesive.','.card{animation-direction:alternate;}','Direcția nu stabilește durata sau numărul de cicluri.',q('Ce face alternate?','Alternează sensul între cicluri','Oprește animația','Șterge elementul'),css('Declară animation-direction alternate pentru .card.','.card{animation-direction:alternate;}','<p class="card">Tea</p>',[prop('.card','animation-direction','alternate')]))
for ch in chapters:
 for item in ch['lessons']:
  if item['id'].startswith('html-modern-'):
   old=item['id'].removeprefix('html-modern-')
   item['task']['contextCode']='<'+old+'>Legacy content</'+old+'>'
   item['task']['contextLabel']='Sintaxa veche pe care o înlocuiești'
T('html-frame-history','Înlocuiește vechea structură cu frame-uri','frameset, frame și noframes aparțin vechii împărțiri a ferestrei în documente. Pentru un layout nou folosește secțiuni și CSS; iframe are alt rol și nu este înlocuitorul automat al întregii structuri.','<frameset cols="30%,70%"><frame src="menu.html"><frame src="content.html"><noframes>Fallback</noframes></frameset>',q('Ce alegi pentru layout-ul unei pagini noi?','Secțiuni HTML și CSS','Un frameset nou','Un frame pentru fiecare paragraf'),'Scrie numele vechiului element părinte din exemplu, fără parantezele unghiulare.','frameset')

c=next(ch for ch in chapters if ch['id']=='js-collections-complete')
def J(id,title,idea,code,cases,prompt):
 lesson(c,id,title,idea,code,idea,q('Ce verifică exercițiul?',title,'Citirea unei baze SQL','Compilarea EJS'),js(prompt,code,cases))
J('array-shift-result','Extrage primul element','shift elimină primul element și îl returnează. Lucrează pe o copie ca să nu modifici input.','function solve(input){const items=[...input]; const first=items.shift();return {first:first??null,items};}',[([3,7],{'first':3,'items':[7]}),([],{'first':None,'items':[]})],'Copiază input, extrage primul element cu shift și returnează {first,items}. Pentru lista goală, first este null.')
J('array-find-index','Poziția primului element potrivit','findIndex returnează indicele primului element care satisface predicatul sau -1. Nu îl confunda cu find, care returnează valoarea.','function solve(input){return input.findIndex(value=>value>=10);}',[([2,11,20],1),([1,2],-1)],'Returnează indicele primei valori de cel puțin 10 cu findIndex; dacă lipsește, -1.')
J('array-concat-copy','Unește două liste cu concat','concat produce o listă nouă. Nu modifică listele inițiale și nu face o copiere profundă a obiectelor conținute.','function solve(input){return input.left.concat(input.right);}',[({'left':[1,2],'right':[3]},[1,2,3]),({'left':[],'right':[7]},[7])],'Primești {left,right}. Unește listele cu concat și returnează rezultatul, fără a modifica input.')
J('string-substr-legacy','Citește substr din cod vechi','substr(start,length) folosește o lungime, spre deosebire de slice(start,end). Este o metodă istorică; în cod nou poți exprima intervalul cu slice.','function solve(input){return input.substr(1,3);}',[('Chocolate','hoc'),('Tea','ea')],'Pentru a interpreta codul vechi, folosește substr(1,3) pe input și returnează textul obținut. Compară apoi cu slice(1,4).')
J('random-selection','Alege un indice dintr-o valoare aleatoare','Math.random produce o valoare de la 0 inclusiv până la 1 exclusiv. Înmulțirea cu lungimea listei și Math.floor produc un indice valid pentru o listă nevidă. În teste primești sample explicit, pentru rezultate reproductibile.','function solve(input){const unit=input.sample??Math.random();return input.items[Math.floor(unit*input.items.length)];}',[({'items':['Cake','Tea'],'sample':0},'Cake'),({'items':['Cake','Tea'],'sample':0.99},'Tea')],'Primești {items,sample}, cu items nevid și sample între 0 inclusiv și 1 exclusiv. Returnează elementul de la Math.floor(sample*items.length). Dacă sample lipsește, folosește Math.random.')

c=next(ch for ch in chapters if ch['id']=='node-integration')
T('node-working-directory','Directorul curent al procesului','process.cwd() indică directorul de lucru al procesului, care poate diferi de __dirname. O cale relativă de fișier este de obicei raportată la directorul de lucru, nu automat la modul.','process.cwd() → /workspace\n__dirname → /workspace/server',q('Pot cwd și __dirname să fie diferite?','Da','Nu','Numai în CSS'),'Conform situației date, scrie directorul curent de lucru.','/workspace')
T('node-listen-port','Ascultă cereri pe un port','listen pornește ascultarea rețelei. Crearea aplicației și definirea rutelor nu deschid singure un port. Laboratorul injectează cereri pentru teste, deci soluțiile exportă aplicația fără listen.','app.listen(8080,()=>console.log("Ready"));',q('Ce reprezintă 8080?','Portul de ascultare','Un id de produs','Numărul de rute'),'Scrie portul pe care aplicația din exemplu ar asculta cereri.','8080')
T('express-template-engine','Configurează motorul de template-uri','app.set stabilește o opțiune a aplicației. view engine alege motorul folosit de render; configurarea motorului nu este o rută.','app.set("view engine","ejs");',q('Ce motor este configurat?','EJS','Sass','PostgreSQL'),'Scrie numele opțiunii configurate în exemplu.','view engine')
T('express-all-methods','Handler pentru toate metodele HTTP','app.all aplică handler-ul aceleiași căi pentru toate metodele HTTP. app.use are reguli de montare de middleware; nu le considera identice în orice situație.','app.all("/status",(req,res)=>res.send(req.method));',q('Ce metode pot ajunge în handler?','GET, POST și celelalte metode HTTP','Doar GET','Doar DELETE'),'Ce text trimite handler-ul pentru o cerere POST /status?','POST')
N('node-lstat-callback','Tipul fișierului prin callback','lstat oferă rezultatul prin callback. Verifică eroarea înainte de a folosi obiectul Stats și isFile sau isDirectory.','const fs=require("fs");function solve(input){return new Promise((resolve,reject)=>fs.lstat(input,(error,stats)=>{if(error)reject(error);else resolve(stats.isFile());}));}',[('data/menu.json',True)],'Returnează un Promise care folosește fs.lstat pentru input și rezolvă cu rezultatul isFile. Fișierul virtual este furnizat.',files={'data/menu.json':'[]'})
